<script setup lang="ts">
import { safeUrl } from '~~/shared/utils/crypto'
import type { ScopedCredential } from '~~/shared/utils/vault-sources'
const props=defineProps<{entries:ScopedCredential[];allEntries:ScopedCredential[];busy:boolean}>()
const emit=defineEmits<{edit:[entry:ScopedCredential];create:[];open:[entry:ScopedCredential]}>()
const query=ref('')
const cards=computed(()=>props.entries.filter(entry=>entry.kind==='relationship'&&`${entry.title} ${entry.url} ${entry.notes}`.toLowerCase().includes(query.value.trim().toLowerCase())))
function connections(entry:ScopedCredential){return (entry.links??[]).map(link=>({link,target:props.allEntries.find(target=>target.id===link.targetEntryId&&(target.vaultIds??[target.vaultId]).includes(link.targetVaultId))}))}
const label=(entry:ScopedCredential)=>entry.kind==='subscription'?'Финансы':entry.kind==='relationship'?'Взаимосвязи':'Пароли'
</script>
<template><section aria-label="Карточки взаимосвязей"><div class="filter-bar"><UInput v-model="query" icon="i-lucide-search" placeholder="Найти сервис, сайт или описание…" aria-label="Поиск карточек взаимосвязей" class="vault-search"/><span>{{ cards.length }} карточек</span></div><div class="relationship-cards-grid"><article v-for="entry in cards" :key="entry.sharedCardId||entry.id" class="relationship-service-card"><button class="relationship-service-title" @click="emit('edit',entry)"><UIcon name="i-lucide-network"/><strong>{{ entry.title }}</strong></button><small>{{ (entry.vaultNames??[entry.vaultName]).join(' · ') }}</small><a v-if="entry.url && safeUrl(entry.url)" class="relationship-service-url" :href="safeUrl(entry.url)" target="_blank" rel="noopener noreferrer" :aria-label="`Открыть сайт: ${entry.title}`"><span>{{ entry.url }}</span><UIcon name="i-lucide-external-link"/></a><p v-else-if="entry.url" class="break-all">{{ entry.url }}</p><p v-if="entry.notes">{{ entry.notes }}</p><div class="relationship-service-links"><template v-for="{link,target} in connections(entry)" :key="link.id"><button v-if="target" @click="emit('open',target)"><span>{{ label(target) }}</span><strong>{{ target.title }}</strong><small v-if="target.financeSubscription">{{ target.financeSubscription.label }}</small><UIcon name="i-lucide-arrow-up-right"/></button><span v-else class="text-xs text-slate-400">Недоступная запись</span></template><p v-if="!entry.links?.length" class="text-xs text-slate-400">Добавьте пароли, подписки или другие карточки.</p></div><UButton color="neutral" variant="outline" label="Открыть карточку" :disabled="busy" @click="emit('edit',entry)"/></article></div><div v-if="!cards.length" class="subscription-empty"><p>{{ query?'Карточки не найдены.':'Создайте карточку сервиса и свяжите её с паролями и подписками.' }}</p><UButton v-if="!query" class="mt-4" icon="i-lucide-plus" label="Добавить карточку" :disabled="busy" @click="emit('create')"/></div></section></template>
